/**
 * Look up CGC census data for a given title+issue.
 * Returns a compact stats object or null if not found.
 */
export function getCensus(title, issue) {
  if (!title || issue == null) return null;
  const key = makeKey(title, String(issue));
  return CENSUS[key] || null;
}

function makeKey(title, issue) {
  let t = title.toLowerCase().replace(/^the\s+/i, '').replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  let i = String(issue).toLowerCase().trim();
  return `${t}_${i}`;
}

/**
 * Format census data as a prompt injection string.
 * Returns empty string if no census data found.
 */
export function formatCensusForPrompt(title, issue) {
  const d = getCensus(title, issue);
  if (!d) return '';
  const lines = [
    `CGC CENSUS DATA FOR THIS SPECIFIC ISSUE (${d.t} #${d.i}):`,
    `Total CGC submissions: ${d.n.toLocaleString()} copies`,
    `Average CGC grade across all submissions: ${d.avg}`,
    `Grade distribution: 9.8=${d.p98}%, 9.6=${d.p96}%, 9.4=${d.p94}%, 9.4+combined=${d.phi}%`,
    `CALIBRATION IMPLICATION: If ${d.phi}% of all submissions grade 9.4 or above, a book`,
    `presenting as high-grade should be graded accordingly — do not cap at 8.5 out of caution.`,
    `Conversely, the average grade of ${d.avg} tells you what most copies actually look like.`,
  ];
  return lines.join('\n');
}
